# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

def make_student(last, first):
    return Student(last + first, last, first, "A")

class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Adler", "Sam")
        ]

    def test_rows_are_sorted_by_last_name(self):
        rows = seating_rows(self.students, 2)
        self.assertEqual(rows, [
            "Row 1: Adler, Sam | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    def test_single_row_when_seats_cover_everyone(self):
        rows = seating_rows(self.students, 10)
        self.assertEqual(len(rows), 1)

    def test_same_last_name_orders_by_first_name(self):
        pair = [make_student("Lowe", "Zed"), make_student("Lowe", "Amy")]
        rows = seating_rows(pair, 2)
        self.assertEqual(rows, ["Row 1: Lowe, Amy | Lowe, Zed"])

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
